/**  One rule, evaluated top to bottom. */
export type RoutingRule = {
	id: string,
	name: string,
	enabled: boolean,
	matcher: RuleMatcher,
	action: RuleAction,
};

/**
 *  Where matching traffic goes.
 * 
 *  Tagged rather than a plain enum because `Group` carries the id of the
 *  group it targets: a rule can never point at a group without naming one.
 */
export type RuleAction = 
/**  Through the selected node. */
{ kind: "proxy" } | 
/**  Straight out, without the proxy. */
{ kind: "direct" } | 
/**  Dropped. */
{ kind: "block" } | 
/**  Through a proxy group; the id refers to a [`crate::domain::group::ProxyGroup`]. */
{ kind: "group"; group_id: string };

/**  What a rule looks at. */
export type RuleMatcher = 
/**  `example.com` and every subdomain. */
{ kind: "domain_suffix"; value: string } | 
/**  Any domain containing the text. */
{ kind: "domain_keyword"; value: string } | 
/**  Exactly this domain. */
{ kind: "domain_full"; value: string } | 
/**
 *  A regular expression tested against the domain, e.g. `^ads?\d+\.`.
 *  Clash spells it `DOMAIN-REGEX`; both kernels understand it, but they
 *  use different syntax dials, so the pattern is passed through verbatim.
 */
{ kind: "domain_regex"; value: string } | 
/**  A named list from the geosite database, e.g. `cn` or `category-ads-all`. */
{ kind: "geo_site"; value: string } | 
/**  An IP range, e.g. `192.168.0.0/16` or `10.0.0.1`. */
{ kind: "ip_cidr"; value: string } | 
/**  A geo database code, e.g. `cn`, `private`. */
{ kind: "geo_ip"; value: string } | 
/**  Destination port. */
{ kind: "port"; value: number } | 
/**  Executable name on this machine, e.g. `chrome.exe`. */
{ kind: "process_name"; value: string } | 
/**
 *  Every pattern in a rule set. `value` is the set id, not the set name:
 *  renaming a set must not break the rules that point at it.
 */
{ kind: "rule_set"; value: string };

export type RuleSet = RuleSet_Serialize | RuleSet_Deserialize;

/**  How the set is kept up to date. */
